document.documentElement.classList.add('js');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});
document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
const statement=document.querySelector('.word-reveal');
statement.innerHTML=statement.innerHTML.split(/(<br>)/).map(part=>part==='<br>'?part:part.split(' ').map(word=>`<span class="word">${word}</span>`).join(' ')).join('');
const words=[...statement.querySelectorAll('.word')];
const wordObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){words.forEach((word,i)=>setTimeout(()=>word.classList.add('lit'),reduced.matches?0:i*100));wordObserver.disconnect()}}),{threshold:.65});wordObserver.observe(statement);
const video=document.querySelector('#hero-video'),videoControl=document.querySelector('.video-control');
function updateVideo(){videoControl.textContent=video.paused?'▷':'Ⅱ';videoControl.setAttribute('aria-label',video.paused?'Play animation':'Pause animation')}
if(reduced.matches)video.pause();
videoControl.addEventListener('click',async()=>{if(video.paused){try{await video.play()}catch{videoControl.setAttribute('aria-label','Animation unavailable')}}else video.pause();updateVideo()});video.addEventListener('play',updateVideo);video.addEventListener('pause',updateVideo);updateVideo();
const audio=document.querySelector('#ambience'),soundButton=document.querySelector('#sound-toggle'),soundLabel=document.querySelector('#sound-label');audio.volume=.5;
soundButton.addEventListener('click',async()=>{if(!audio.paused){audio.pause();soundButton.setAttribute('aria-pressed','false');soundLabel.textContent='SOUND OFF';return}try{await audio.play();soundButton.setAttribute('aria-pressed','true');soundLabel.textContent='SOUND ON'}catch{soundLabel.textContent='TRY SOUND AGAIN';soundButton.setAttribute('aria-pressed','false')}});
document.querySelectorAll('[data-layout]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-layout]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelector('#paper').className='paper '+button.dataset.layout}));
const menuToggle=document.querySelector('.menu-toggle'),menu=document.querySelector('.mobile-menu');function closeMenu(){menu.hidden=true;menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Open menu');document.body.style.overflow=''}
menuToggle.addEventListener('click',()=>{const open=menuToggle.getAttribute('aria-expanded')!=='true';menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Close menu':'Open menu');menu.hidden=!open;document.body.style.overflow=open?'hidden':''});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu()});
document.querySelector('#brief-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);const content=`FOLIO / YOUR NEXT CHAPTER\nProject brief\n\nAuthor: ${data.get('author')}\nEmail: ${data.get('email')}\nService: ${data.get('service')}\nApproximate word count: ${data.get('words')}\n\nAbout the book\n${data.get('story')}\n\nNext steps\nShare this brief with your chosen design team to agree on deliverables, schedule, pricing and revision rounds.\n\nPrepared locally. This brief has not been sent to an agency.\n`;const blob=new Blob([content],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='Folio-project-brief.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('.form-status').textContent='Your brief is ready. Check your downloads, then share it with your design team. No inquiry has been sent.'});
const dialog=document.querySelector('#policy-dialog');const policies={privacy:['Privacy','This concept website does not send project form entries to a server. A project brief is created on your device only when you request a download. The site does not use analytics or advertising cookies.','Video and audio are served as site assets. The Manrope typeface is requested from Google Fonts, which receives standard connection information. Hosting providers may process routine technical request logs. Avoid including confidential manuscript content in your brief.'],terms:['Terms','Folio is an agency website concept. Service descriptions illustrate the proposed offer and do not constitute a signed service agreement, quotation, or guarantee of publication or sales.','Before commissioning work, agree on deliverables, cost, schedule, revision rounds, ownership, and the publishing platform requirements with your provider. The project brief tool downloads a file and does not place an order or send an inquiry.']};document.querySelectorAll('[data-policy]').forEach(button=>button.addEventListener('click',()=>{const policy=policies[button.dataset.policy];document.querySelector('#policy-title').textContent=policy[0];const body=document.querySelector('#policy-body');body.replaceChildren(...policy.slice(1).map(text=>{const p=document.createElement('p');p.textContent=text;return p}));dialog.showModal()}));document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close()}});document.querySelector('#year').textContent=new Date().getFullYear();
